/**
 * Command model types (docs/GUI_UX_SPEC.md §23).
 *
 * A Command is a *stateless* description: predicates receive a
 * CommandSnapshot so the same definitions can be evaluated for menus,
 * keyboard dispatch, palette listing and tests without re-registering.
 */

/** Pitch display modes (GUI_UX_SPEC §7). Kept literal here so the command
 *  layer does not depend on a component file. */
export type PitchViewSetting = "concert" | "hornF";

/** Top-level screens that gate command availability. */
export type AppView = "workspace" | "settings";

/** Grouping for menus / command palette / docs. */
export type CommandSection =
  | "file"
  | "score"
  | "transport"
  | "view"
  | "review"
  | "edit"
  | "export"
  | "nav"
  | "app";

/**
 * Immutable read of the app state that command predicates evaluate.
 * The app builds one per render; the registry never stores it.
 */
export interface CommandSnapshot {
  /** A source audio file is loaded (GUI_UX_SPEC §4, AUDIO_READY+). */
  readonly hasAudio: boolean;
  /** A canonical score exists (SCORE_READY+). */
  readonly hasScore: boolean;
  /** Transcription is running — score-writing commands disable (§5). */
  readonly isTranscribing: boolean;
  /** Audio is currently playing (drives the play/pause affordance). */
  readonly isPlaying: boolean;
  /** Loop range playback is armed. */
  readonly loopEnabled: boolean;
  /** Current pitch display mode. */
  readonly pitch: PitchViewSetting;
  /** Undo/redo stacks (§14 — all edits are commands). */
  readonly canUndo: boolean;
  readonly canRedo: boolean;
  /** A note/region is selected (gates Esc = clear selection). */
  readonly hasSelection: boolean;
  /** #163: the score selection is a rest glyph — gates restToNote. */
  readonly hasRestSelection: boolean;
  /** #113: a waveform range selection exists (AUDIO_READY). Esc clears
   *  this before any score selection (spec 8: Esc -> 選択解除). */
  readonly hasWaveformSelection: boolean;
  /** 要確認 workspace state. */
  readonly reviewOpen: boolean;
  readonly reviewCount: number;
  /** FEAT-001: a recording session is in progress (loopback/mic). */
  readonly isRecording: boolean;
  /** FEAT-001 (#80): the recording session is paused. */
  readonly isRecordingPaused: boolean;
  /** FEAT-001: score audition (auto-playback of the score) is on. */
  readonly auditionEnabled: boolean;
  /** Active top-level view. */
  readonly view: AppView;
}

/**
 * The services commands act on. The app supplies implementations; during
 * the spike most are stubs that announce via `announce` so every invocation
 * produces honest feedback in the (aria-live) status bar.
 */
export interface CommandContext {
  openAudio(): void;
  /** Start a transcription job. #148: callers may pin option overrides
   *  (e.g. the review bar's voices-texture retry) without mutating the
   *  stored settings first — avoids a stale-options race. */
  transcribe(overrides?: {
    texture?: "auto" | "mono" | "melody" | "voices" | "chords";
  }): void;
  /**
   * Cooperative `job.cancel` (UI-040): requests cancellation of the
   * in-flight transcription; the job still ends in a terminal `cancelled`
   * event, so callers must not assume an instant stop. Optional so older
   * test contexts keep compiling — an absent implementation is a no-op.
   */
  cancelTranscription?(): void;
  togglePlayPause(): void;
  stop(): void;
  jumpBack(): void;
  jumpForward(): void;
  seekToStart(): void;
  seekToEnd(): void;
  toggleLoop(): void;
  /**
   * FEAT-001 (#60): PC再生音源/マイク録音と楽譜自動演奏。
   * Optional so older test contexts keep compiling.
   */
  captureSystemAudio?(): void;
  captureMicrophone?(): void;
  /** 録音中なら停止して取り込む / 録音していなければ何もしない。 */
  stopCapture?(): void;
  /** 録音を中止して破棄する。 */
  cancelCapture?(): void;
  /** 録音を一時停止する(#80)。 */
  pauseCapture?(): void;
  /** 一時停止した録音を再開する(#80)。 */
  resumeCapture?(): void;
  /** 楽譜の自動演奏トグル(スコアクロックに同期して発音)。 */
  toggleScoreAudition?(): void;
  /** 元音源のミュート切替(#72)。楽譜の演奏だけを聴く用途。 */
  toggleSourceMute?(): void;
  setPitchView(view: PitchViewSetting): void;
  openReview(): void;
  reviewNext(): void;
  reviewPrevious(): void;
  /**
   * UI-050 review-workspace actions (GUI_UX_SPEC §12). Optional like
   * `cancelTranscription` so leaner test contexts keep compiling — an
   * absent implementation is a no-op.
   */
  reviewAccept?(): void;
  reviewDismiss?(): void;
  reviewPlaySource?(): void;
  reviewPitchUp?(): void;
  reviewPitchDown?(): void;
  reviewDeleteOrRestore?(): void;
  exitReview?(): void;
  undo(): void;
  redo(): void;
  openExport(): void;
  /** §13 高度編集: open the live score in the MuseScore GUI (async —
   *  the implementation announces success/failure itself). Optional:
   *  absent = no-op. */
  openInMuseScore?(): void;
  /** #100: プロジェクトを保存 — opens the save-file picker and writes
   *  .hornscribe.json through the engine. Optional like the other
   *  late-binding commands; absent = no-op. */
  saveProject?(): void;
  zoomScoreIn(): void;
  zoomScoreOut(): void;
  zoomScoreFit(): void;
  clearSelection(): void;
  /** #114 (spec 10): select the previous/next note (score workspace). */
  selectAdjacentNote?(direction: 1 | -1): void;
  /** #114 (spec 13): semitone-shift / delete / respell the selected
   *  note outside the review workspace (undoable). */
  editSelectedPitch?(delta: number): void;
  toggleSelectedDeleted?(): void;
  toggleSelectedEnharmonic?(): void;
  /** #115 (spec 13): engine rhythm edits on the selected note —
   *  duration ladder (+1 = ×2, -1 = ÷2), onset shift by min-grid steps,
   *  tie/untie to the contiguous next same-pitch note. Async: the
   *  implementation announces success/failure itself. Optional so
   *  fixture/test contexts keep compiling — absent = no-op. */
  noteDurationScale?(power: number): void;
  shiftSelectedOnset?(steps: number): void;
  toggleSelectedTie?(): void;
  /** #130 (spec 14): open the quantization-settings dialog — the
   *  requantize edit itself is applied via the score controller. */
  openRequantizeDialog?(): void;
  /** #131 (spec 13 post-MVP): split/merge the selected note. */
  splitSelectedNote?(): void;
  mergeSelectedNotes?(): void;
  /** #163: convert the selected rest to a note (missed detection). */
  convertSelectedRest?(): void;
  /** #113: Esc on a waveform selection (AUDIO_READY) - clears the range
   *  back to "all" (spec 8: Esc -> 選択解除). Optional: absent = no-op. */
  clearWaveformSelection?(): void;
  openSettings(): void;
  /** Opens the 診断情報 sheet (§19 — separated from the normal UI). */
  openDiagnostics(): void;
  /** F6 region navigation — implemented by focus/zones. */
  focusNextRegion(): void;
  focusPreviousRegion(): void;
  /**
   * Surface command feedback in the status area (role="status" is
   * aria-live, so Narrator users hear the result — UX_VALIDATION §11).
   */
  announce(message: string): void;
}

/**
 * A single invocable command — the unit the registry, command bar, menus,
 * palette and keyboard dispatcher all share (single source of truth).
 */
export interface Command {
  /** Stable dotted id, e.g. "transport.playPause". */
  readonly id: string;
  /**
   * Japanese title — the only UI language (UI_COPY_CONTRACT). This is what
   * buttons, menus, a palette and screen readers all announce.
   */
  readonly title: string;
  /** Optional longer Japanese description for palettes/menus. */
  readonly description?: string;
  readonly section: CommandSection;
  /**
   * Keyboard bindings in "Ctrl+Shift+Z" notation; whitespace separates
   * chords in a multi-step sequence. The first entry is the canonical
   * binding shown in tooltips / aria-keyshortcuts.
   */
  readonly shortcuts?: readonly string[];
  /**
   * #114: opt-in to sharing a chord with another command whose
   * `isEnabled` predicate is mutually exclusive (e.g. ArrowRight =
   * review.next while reviewing, score.selectNext otherwise). Every
   * command on the shared chord must set this flag; the dispatcher
   * activates the first *enabled* candidate.
   */
  readonly shareShortcut?: boolean;
  /**
   * May run against this snapshot. Default: enabled. Disabled commands are
   * non-executable everywhere — toolbar, menu AND shortcut (issue req:
   * "disabled commands remain non-executable via shortcut").
   */
  readonly isEnabled?: (snapshot: CommandSnapshot) => boolean;
  /**
   * Listed on command surfaces (palette/menus/overflow). Default: visible.
   * Hidden commands still run when enabled — e.g. 採譜し直す vs 採譜.
   */
  readonly isVisible?: (snapshot: CommandSnapshot) => boolean;
  /** May fire while a text field / IME host has focus. Default false. */
  readonly allowInTextInput?: boolean;
  /** May fire while a modal dialog/sheet owns focus. Default false. */
  readonly allowInModal?: boolean;
  /** Re-fires on key auto-repeat. Default false (no accidental toggles). */
  readonly allowRepeat?: boolean;
  /** Execute against live services. */
  readonly run: (ctx: CommandContext, snapshot: CommandSnapshot) => void;
}

/**
 * Import-owned score-region bodies (UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * ScoreWorkspace delegates the import-side machine states here:
 *   empty         → drop headline + 開く CTA + formats + trust + recents
 *   openingAudio  → honest indeterminate progress (§5: no fake %)
 *   audioReady    → file metadata + 採譜を開始 + 採譜オプション popover
 *   audioError    → copy-deck error card (別のファイルを選ぶ / 閉じる)
 *   sourceMissing → 元音源が見つかりません card (音源を指定 / 閉じる)
 *
 * All copy resolves through ja.import / ja.emptyState / ja.score — the
 * copy deck (protocol/copy/ja-JP.json) is the source of truth.
 */
import {
  ErrorCircle24Regular,
  FolderOpen24Regular,
  History24Regular,
  Play24Regular,
  Mic24Regular,
  Speaker2Regular,
} from "@fluentui/react-icons";
import { ja } from "../strings/ja";
import { HsButton } from "../components/primitives/Button";
import { HsNumericField } from "../components/primitives/NumericField";
import { HsPopover } from "../components/primitives/Popover";
import { HsProgress } from "../components/primitives/Progress";
import { HsSelect, type HsSelectOption } from "../components/primitives/Select";
import type { ScreenState } from "../workspace/screen";
import { formatBytes, formatDuration } from "./format";
import type {
  ImportIssue,
  LoadedAudio,
  RecentProjectEntry,
  SourceMissingInfo,
  TranscriptionOptions,
} from "./types";
import { issueText, type CaptureState } from "../capture/controller";

/** Everything the import-owned bodies need — assembled once in App and
 *  handed down through ScoreWorkspace (keeps that shared file's diff small
 *  for the sibling feature teams). */
export interface ImportView {
  audio: LoadedAudio | null;
  openingLabel: string | null;
  openingKind: "audio" | "project" | null;
  /** AUDIO_ERROR card content (no-audio failures). */
  issue: ImportIssue | null;
  /** SOURCE_MISSING context (project + last relink outcome). */
  sourceMissing: SourceMissingInfo | null;
  recentProjects: readonly RecentProjectEntry[];
  options: TranscriptionOptions;
  onOpenAudio(): void;
  onOpenProject(entry: RecentProjectEntry): void;
  onPickRelink(): void;
  onDismissError(): void;
  onOptionsChange(next: TranscriptionOptions): void;
  /** FEAT-001 (#60): capture controls on the EMPTY state. */
  captureState?: CaptureState | null;
  onStartCapture?(source: "loopback" | "microphone"): void;
}

/** Routes the import-owned screen states to their bodies. */
export function ImportScreenBody({
  screen,
  view,
  onTranscribe,
}: {
  screen: ScreenState;
  view: ImportView;
  onTranscribe(): void;
}) {
  switch (screen) {
    case "empty":
      return <EmptyStateBody view={view} />;
    case "openingAudio":
      return <OpeningAudioBody view={view} />;
    case "audioReady":
      return <AudioReadyBody view={view} onTranscribe={onTranscribe} />;
    case "audioError":
      return <AudioErrorBody view={view} />;
    case "sourceMissing":
      return <SourceMissingBody view={view} />;
    default:
      return null;
  }
}

/* ------------------------------ EMPTY (§3) ------------------------------ */

function EmptyStateBody({ view }: { view: ImportView }) {
  return (
    <div className="hs-empty">
      <p className="hs-empty__title">{ja.emptyState.title}</p>
      <p className="hs-empty__or">{ja.emptyState.or}</p>
      <HsButton
        variant="primary"
        size="large"
        icon={<FolderOpen24Regular />}
        onClick={view.onOpenAudio}
      >
        {ja.emptyState.open}
      </HsButton>
      <p className="hs-empty__formats">{ja.emptyState.formats}</p>
      {/* FEAT-001: 録音による取り込み — ファイルを持たない入力経路。 */}
      {view.onStartCapture ? (
        <div className="hs-empty__capture">
          <p className="hs-empty__capture-title">
            {ja.emptyState.captureTitle}
          </p>
          <div className="hs-empty__capture-actions">
            <HsButton
              variant="secondary"
              icon={<Speaker2Regular />}
              disabled={view.captureState?.phase === "recording"}
              onClick={() => view.onStartCapture!("loopback")}
            >
              {ja.emptyState.captureLoopback}
            </HsButton>
            <HsButton
              variant="secondary"
              icon={<Mic24Regular />}
              disabled={view.captureState?.phase === "recording"}
              onClick={() => view.onStartCapture!("microphone")}
            >
              {ja.emptyState.captureMic}
            </HsButton>
          </div>
          <p className="hs-empty__capture-hint">
            {ja.emptyState.captureHint}
          </p>
          {/* 録音開始の失敗(デバイス無し等)はここに表示する —
              ステータス行だけでは EMPTY 画面で見落とされる。 */}
          {view.captureState?.phase === "error" &&
          view.captureState.issue ? (
            <p className="hs-empty__capture-error" role="alert">
              {issueText(view.captureState.issue)}
            </p>
          ) : null}
        </div>
      ) : null}
      <p className="hs-empty__privacy">{ja.emptyState.privacy}</p>
      {/* §3: 履歴がある場合のみ「最近使ったプロジェクト」 */}
      {view.recentProjects.length > 0 ? (
        <div
          className="hs-recent"
          role="group"
          aria-label={ja.import.recent.title}
        >
          <p className="hs-recent__title">{ja.import.recent.title}</p>
          <ul className="hs-recent__list">
            {view.recentProjects.map((entry) => (
              <li key={entry.path}>
                <button
                  type="button"
                  className="hs-recent__item"
                  title={entry.path}
                  aria-label={ja.import.recent.openAria(entry.name)}
                  onClick={() => view.onOpenProject(entry)}
                >
                  <History24Regular aria-hidden="true" />
                  <span className="hs-recent__name">{entry.name}</span>
                </button>
              </li>
            ))}
          </ul>
        </div>
      ) : null}
    </div>
  );
}

/* --------------------------- OPENING_AUDIO --------------------------- */

function OpeningAudioBody({ view }: { view: ImportView }) {
  const title =
    view.openingKind === "project"
      ? ja.import.opening.project
      : ja.import.opening.audio;
  return (
    <div className="hs-empty hs-opening" role="status">
      <p className="hs-opening__title">{title}</p>
      {/* §5: indeterminate — decode time is not honestly predictable. */}
      <HsProgress label={title} className="hs-opening__progress" />
      {view.openingLabel ? (
        <p className="hs-opening__name">{view.openingLabel}</p>
      ) : null}
    </div>
  );
}

/* --------------------------- AUDIO_READY (§4) --------------------------- */

const TEMPO_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.tempoAuto },
  { value: "manual", label: ja.import.audioOptions.tempoManual },
];
const METER_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.meterAuto },
  { value: "4/4", label: "4/4" },
  { value: "3/4", label: "3/4" },
  { value: "6/8", label: "6/8" },
  { value: "2/4", label: "2/4" },
  { value: "5/4", label: "5/4" },
  { value: "7/8", label: "7/8" },
  { value: "9/8", label: "9/8" },
  { value: "12/8", label: "12/8" },
];
const MIN_DURATION_OPTIONS: readonly HsSelectOption[] = [
  { value: "8", label: ja.import.audioOptions.minDuration8 },
  { value: "16", label: ja.import.audioOptions.minDuration16 },
  { value: "32", label: ja.import.audioOptions.minDuration32 },
];
const TRIPLET_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.tripletsAuto },
  { value: "allow", label: ja.import.audioOptions.tripletsAllow },
  { value: "none", label: ja.import.audioOptions.tripletsNone },
];
const SIMPLICITY_OPTIONS: readonly HsSelectOption[] = [
  { value: "standard", label: ja.import.audioOptions.simplicityStandard },
  { value: "simple", label: ja.import.audioOptions.simplicitySimple },
  { value: "detailed", label: ja.import.audioOptions.simplicityDetailed },
];
const TEXTURE_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.textureAuto },
  { value: "mono", label: ja.import.audioOptions.textureMono },
  { value: "melody", label: ja.import.audioOptions.textureMelody },
  { value: "voices", label: ja.import.audioOptions.textureVoices },
  { value: "chords", label: ja.import.audioOptions.textureChords },
];
const BACKEND_OPTIONS: readonly HsSelectOption[] = [
  { value: "auto", label: ja.import.audioOptions.backendAuto },
  { value: "basicPitch", label: "Basic Pitch" },
  { value: "pyin", label: "pYIN（単音）" },
];
const RANGE_OPTIONS: readonly HsSelectOption[] = [
  { value: "all", label: ja.import.audioOptions.rangeAll },
  // #88: 時刻指定の範囲採譜。波形ドラッグ選択は別issueで検討中だが、
  // 秒数入力だけでも「ソロ部分だけ採譜」は実用になる。
  { value: "selection", label: ja.import.audioOptions.rangeSelection },
];

function AudioReadyBody({
  view,
  onTranscribe,
}: {
  view: ImportView;
  onTranscribe(): void;
}) {
  const { audio, options } = view;
  const set = (patch: Partial<TranscriptionOptions>) =>
    view.onOptionsChange({ ...options, ...patch });
  return (
    <div className="hs-empty hs-audio-ready">
      <p className="hs-score__empty-title">{ja.score.empty}</p>
      {audio ? (
        <p className="hs-audio-ready__meta">
          <span className="hs-audio-ready__name">{audio.fileName}</span>
          <span aria-hidden="true">・</span>
          <span>{audio.format.toUpperCase()}</span>
          <span aria-hidden="true">・</span>
          <span>{formatDuration(audio.durationSeconds)}</span>
          <span aria-hidden="true">・</span>
          <span>{formatBytes(audio.sizeBytes)}</span>
        </p>
      ) : null}
      <div className="hs-audio-ready__actions">
        <HsButton
          variant="primary"
          size="large"
          icon={<Play24Regular />}
          onClick={onTranscribe}
        >
          {ja.score.transcribeStart}
        </HsButton>
        {/* §4: advanced transcription settings live in the popover next to
            the primary action — hidden by default. */}
        <HsPopover
          ariaLabel={ja.import.audioOptions.label}
          positioning="above"
          trigger={
            <HsButton variant="subtle">
              {ja.import.audioOptions.label}
            </HsButton>
          }
        >
          <div className="hs-audio-options">
            <p className="hs-audio-options__title">
              {ja.import.audioOptions.label}
            </p>
            <HsSelect
              label={ja.import.audioOptions.texture}
              options={TEXTURE_OPTIONS}
              value={options.texture}
              onChange={(v) =>
                set({ texture: v as TranscriptionOptions["texture"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.backend}
              options={BACKEND_OPTIONS}
              value={options.backend}
              hint={ja.import.audioOptions.backendHint}
              onChange={(v) =>
                set({ backend: v as TranscriptionOptions["backend"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.tempo}
              options={TEMPO_OPTIONS}
              value={options.tempo}
              onChange={(v) =>
                set({ tempo: v as TranscriptionOptions["tempo"] })
              }
            />
            {options.tempo === "manual" ? (
              <HsNumericField
                label={ja.import.audioOptions.tempoBpm}
                value={options.tempoBpm}
                min={30}
                max={300}
                step={1}
                unit="BPM"
                onChange={(v) => set({ tempoBpm: v })}
              />
            ) : null}
            <HsSelect
              label={ja.import.audioOptions.meter}
              options={METER_OPTIONS}
              value={options.meter}
              onChange={(v) => set({ meter: v })}
            />
            <HsSelect
              label={ja.import.audioOptions.minDuration}
              options={MIN_DURATION_OPTIONS}
              value={options.minDuration}
              onChange={(v) => set({ minDuration: v })}
            />
            <HsSelect
              label={ja.import.audioOptions.triplets}
              options={TRIPLET_OPTIONS}
              value={options.triplets}
              onChange={(v) =>
                set({ triplets: v as TranscriptionOptions["triplets"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.simplicity}
              options={SIMPLICITY_OPTIONS}
              value={options.simplicity}
              onChange={(v) =>
                set({ simplicity: v as TranscriptionOptions["simplicity"] })
              }
            />
            <HsSelect
              label={ja.import.audioOptions.range}
              options={RANGE_OPTIONS}
              value={options.range}
              onChange={(v) =>
                set({ range: v as TranscriptionOptions["range"] })
              }
            />
            {options.range === "selection" && audio ? (
              <>
                <HsNumericField
                  label={ja.import.audioOptions.rangeStart}
                  value={options.selectionStartSec}
                  min={0}
                  max={audio.durationSeconds}
                  step={0.5}
                  unit={ja.import.audioOptions.secondsUnit}
                  onChange={(v) => set({ selectionStartSec: v })}
                />
                <HsNumericField
                  label={ja.import.audioOptions.rangeEnd}
                  value={options.selectionEndSec}
                  min={0}
                  max={audio.durationSeconds}
                  step={0.5}
                  unit={ja.import.audioOptions.secondsUnit}
                  onChange={(v) => set({ selectionEndSec: v })}
                />
              </>
            ) : null}
          </div>
        </HsPopover>
      </div>
    </div>
  );
}

/* ------------------------------ errors (§20) ------------------------------ */

/** Copy-deck error copy per issue kind — shared by the AUDIO_ERROR card
 *  and the modal dialog shown when a re-import fails over a live session. */
export function issueCopy(issue: ImportIssue): {
  title: string;
  body: string;
  fileName?: string;
} {
  switch (issue.kind) {
    case "unsupported":
      return {
        title: ja.import.errors.unsupportedTitle,
        body: ja.import.errors.unsupportedBody,
        fileName: issue.fileName,
      };
    case "openFailed":
      return {
        title: ja.import.errors.openFailedTitle,
        body: ja.import.errors.openFailedBody,
        fileName: issue.fileName,
      };
    case "projectOpenFailed":
      return {
        title: ja.import.errors.projectOpenFailedTitle,
        body: ja.import.errors.projectOpenFailedBody,
        fileName: issue.fileName,
      };
  }
}

function AudioErrorBody({ view }: { view: ImportView }) {
  const issue = view.issue ?? { kind: "openFailed" as const };
  const copy = issueCopy(issue);
  const canPickAnother = issue.kind !== "projectOpenFailed";
  return (
    <div className="hs-empty hs-error" role="alert">
      <ErrorCircle24Regular
        className="hs-error__icon"
        aria-hidden="true"
      />
      <p className="hs-error__title">{copy.title}</p>
      {copy.fileName ? (
        <p className="hs-error__file">{copy.fileName}</p>
      ) : null}
      <p className="hs-error__body">{copy.body}</p>
      <div className="hs-error__actions">
        {canPickAnother ? (
          <HsButton variant="primary" onClick={view.onOpenAudio}>
            {ja.import.errors.chooseAnother}
          </HsButton>
        ) : null}
        <HsButton
          variant={canPickAnother ? "secondary" : "primary"}
          onClick={view.onDismissError}
        >
          {ja.import.errors.close}
        </HsButton>
      </div>
    </div>
  );
}

function SourceMissingBody({ view }: { view: ImportView }) {
  const info = view.sourceMissing;
  const mismatch = info?.mismatch === true;
  return (
    <div className="hs-empty hs-error" role="alert">
      <ErrorCircle24Regular
        className="hs-error__icon"
        aria-hidden="true"
      />
      <p className="hs-error__title">
        {mismatch
          ? ja.import.errors.hashMismatchTitle
          : ja.import.errors.sourceMissingTitle}
      </p>
      {info?.project.sourcePath ? (
        <p className="hs-error__file" title={info.project.sourcePath}>
          {ja.import.errors.lastLocation}
          {info.project.sourcePath}
        </p>
      ) : null}
      <p className="hs-error__body">
        {mismatch
          ? ja.import.errors.hashMismatchBody
          : ja.import.errors.sourceMissingBody}
      </p>
      <div className="hs-error__actions">
        <HsButton variant="primary" onClick={view.onPickRelink}>
          {mismatch
            ? ja.import.errors.specifyAnother
            : ja.import.errors.specifySource}
        </HsButton>
        <HsButton variant="secondary" onClick={view.onDismissError}>
          {ja.import.errors.close}
        </HsButton>
      </div>
    </div>
  );
}

/**
 * Import domain types (issue #25 / UI-020; docs/GUI_UX_SPEC.md §3/§4/§20).
 *
 * The import flow turns a user-picked file into a `LoadedAudio` the shell
 * can draw (waveform peaks + metadata) and play (UI-004 TransportController
 * contract media source), or into a recoverable `ImportIssue` rendered with
 * the copy-deck error shape (what failed / what is kept / next action).
 */

/** Advertised container formats (GUI_UX_SPEC §3: WAV・MP3・FLAC・M4A・OGG). */
export type AudioFormat = "wav" | "mp3" | "flac" | "m4a" | "ogg";

/**
 * A user-selected audio file. Inside Tauri the native dialog and the
 * window drag-drop event hand us real filesystem paths; in plain-browser
 * dev sessions the HTML drop/file-input hands us `File` objects.
 */
export type AudioFileRef =
  | { kind: "path"; path: string; name: string }
  | { kind: "file"; file: File; name: string };

/**
 * FEAT-001 (#60): 録音由来の疑似ファイル参照。
 * `kind: "recording"` はディスク上の実ファイルではなく、メモリ上の
 * 録音バッファを表す。`mediaSource.blob` に録音結果が入るので、
 * `LoadedAudio` としては既存経路と同じ振る舞いをする。
 */
export type RecordedAudioRef = {
  kind: "recording";
  /** UI 表示用の仮想ファイル名(例: "録音_20260922_153000.wav")。 */
  name: string;
  /** "loopback" | "microphone" — どこから録ったか。 */
  source: "loopback" | "microphone";
  /** Tauri: appDataDir/recordings/ に保存済みの実ファイルパス(#70)。
   *  ある場合は内容がディスク上に永続化されており、プロジェクトの
   *  sourceAudio(originalPath/contentHash)に載せられる。 */
  path?: string;
  /** path を持つ録音の SHA-256(FND-001 の contentHash 契約)。 */
  contentHash?: string;
  /** ブラウザ dev 等、実ファイルが無い場合の録音バイト列。 */
  blob?: Blob;
};

/**
 * What the UI-004 TransportController contract can load — mirrors the
 * spike's `AudioSource` (url | blob). We always hand over a blob: either
 * the dropped `File` itself or a Blob built from `read_audio_bytes`, so the
 * user-owned source file is only ever read, never modified.
 */
export type MediaSource = { kind: "url"; url: string } | { kind: "blob"; blob: Blob };

/** Fully decoded audio ready for the AUDIO_READY state (GUI_UX_SPEC §4). */
export interface LoadedAudio {
  /** Where the bytes came from (kept for relink/re-open bookkeeping). */
  ref: AudioFileRef | RecordedAudioRef;
  fileName: string;
  format: AudioFormat;
  sizeBytes: number;
  /** Audio-clock duration in seconds (0 while unknown). */
  durationSeconds: number;
  sampleRate: number;
  /** Normalized peak amplitudes 0–1 for the waveform strip. */
  peaks: readonly number[];
  /** Playback-ready source for the transport adapter. */
  mediaSource: MediaSource;
}

/**
 * Recoverable import failures — every variant has a copy-deck title/body
 * plus a recovery action, so errors never dead-end (acceptance: "invalid
 * file has actionable Japanese error", "unsupported codec does not
 * dead-end").
 */
export type ImportIssue =
  /** Extension is not in the advertised set — honest format guidance. */
  | { kind: "unsupported"; fileName: string }
  /** Read/decode failed (corrupt file, vanished path, codec the webview
      cannot decode and FFmpeg normalization has not landed yet). */
  | { kind: "openFailed"; fileName?: string }
  /** `.hornscribe.json` could not be read or parsed. */
  | { kind: "projectOpenFailed"; fileName: string };

/**
 * The subset of `HornScribeProject` (python/hornscribe/project/model.py,
 * schema v1) the relink UX needs. `sourcePath`/`sourceHash` mirror
 * `sourceAudio.originalPath` / `contentHash`.
 */
export interface ProjectSummary {
  /** Absolute path of the .hornscribe.json file itself. */
  path: string;
  projectId: string;
  /** Display name — file basename without the .hornscribe.json suffix. */
  name: string;
  sourcePath: string | null;
  sourceHash: string | null;
  /** Saved job-result extras (#106): when the file carries
   *  musicXmlConcert/musicXmlHornF + score.revision + reviewIssues,
   *  this mirrors the completed-job `result` payload so the score can
   *  be restored without re-transcribing. Null for projects without
   *  saved score data (externally authored files). */
  scoreResult: unknown | null;
}

/** SOURCE_MISSING context: which project lost its audio, and whether the
 *  last relink candidate failed the content-hash check (deck:
 *  sourceMoved vs sourceHashMismatch copy). */
export interface SourceMissingInfo {
  project: ProjectSummary;
  mismatch: boolean;
}

/** A "最近使ったプロジェクト" entry (GUI_UX_SPEC §3). */
export interface RecentProjectEntry {
  name: string;
  path: string;
  /** Epoch ms of the last successful open (sorting + pruning). */
  openedAt: number;
}

/**
 * 採譜オプション (GUI_UX_SPEC §4 advanced options — hidden in the popover
 * next to 採譜を開始). Values are option keys; Japanese labels resolve via
 * ja.import.audioOptions. Consumed by the transcription feature (UI-040),
 * persisted nowhere yet.
 */
export interface TranscriptionOptions {
  tempo: "auto" | "manual";
  tempoBpm: number | null;
  meter: string;
  minDuration: string;
  triplets: "auto" | "allow" | "none";
  simplicity: "standard" | "simple" | "detailed";
  range: "all" | "selection";
  /** 音源の種類 — mono=単旋律楽器, melody=メロディ優先(ミックス/JPOP),
      auto=重なりの多さからエンジンが自動判定。 */
  texture: "auto" | "mono" | "melody" | "voices" | "chords";
  /** #189: per-job engine override. "auto" inherits the global
   *  設定→詳細設定 backend; an explicit choice pins this job only. */
  backend: "auto" | "basicPitch" | "pyin";
  /** 範囲指定時の開始/終了（秒）。null = 音声の端まで。 */
  selectionStartSec: number | null;
  selectionEndSec: number | null;
}

export const DEFAULT_TRANSCRIPTION_OPTIONS: TranscriptionOptions = {
  tempo: "auto",
  tempoBpm: null,
  meter: "auto",
  minDuration: "16",
  triplets: "auto",
  simplicity: "standard",
  range: "all",
  texture: "auto",
  backend: "auto",
  selectionStartSec: null,
  selectionEndSec: null,
};

"""Canonical score model (FND-001).

A ScoreDocument is *concert pitch only*. Horn in F is a derived presentation
of the same canonical notes and therefore shares canonical note IDs.

Timing model: score positions are rational beat positions (Fraction), never
float seconds. Source seconds are reachable only through the tempo map /
provenance layer.
"""

from __future__ import annotations

import uuid
from dataclasses import dataclass, field
from enum import Enum
from fractions import Fraction
from itertools import pairwise
from typing import Any

from hornscribe.domain.events import PitchBendPoint
from hornscribe.domain.ids import (
    ProjectId,
    RawNoteEventId,
    ScoreNoteId,
    ScoreRevisionId,
    derive_score_revision_id,
)


class PitchSpace(Enum):
    """The only pitch space allowed for canonical storage is CONCERT."""

    CONCERT = "concert"
    WRITTEN_HORN_F = "written_horn_f"  # presentation/export only, never canonical


@dataclass(frozen=True)
class ScoreAtom:
    """One written symbol inside a canonical note or rest (QNT-006).

    ``duration_beats`` is the atom's exact span on the canonical beat axis;
    ``symbol`` + ``dots`` + ``tuplet`` describe how it is written. These are
    the quantizer's committed notation decisions — HSQ decides the written
    decomposition, the notation layer only renders it (architecture rule:
    music21 realizes/serializes, never re-quantizes).

    ``tie_to_next`` joins this atom to the following atom *inside the same
    canonical note's* atom list; it is always ``False`` on a note's last atom
    and always ``False`` on rest atoms (rests never tie).
    """

    duration_beats: Fraction
    """Exact span of the written symbol (e.g. a triplet eighth = 1/3 beat in
    a quarter-note-beat meter)."""
    symbol: str
    """Base symbol name: ``"whole"``, ``"half"``, ``"quarter"``, ``"eighth"``,
    ``"sixteenth"``, ``"32nd"``, ``"64th"``."""
    dots: int = 0
    tuplet: str | None = None
    """Tuplet label (``"triplet"`` in HSQ-v1), or ``None`` for binary atoms."""
    tuplet_group_start: bool = False
    """``True`` when this atom opens a new visual tuplet group (MusicXML
    ``<tuplet type="start">``); the last tuplet atom before the next
    ``tuplet_group_start``/non-tuplet atom closes it."""
    tie_to_next: bool = False

    def __post_init__(self) -> None:
        object.__setattr__(self, "duration_beats", _unfrac(self.duration_beats))
        if self.duration_beats <= 0:
            raise ValueError(f"atom duration_beats must be > 0, got {self.duration_beats}")
        if not self.symbol:
            raise ValueError("atom symbol must be a non-empty string")
        if (
            isinstance(self.dots, bool)
            or not isinstance(self.dots, int)
            or not 0 <= self.dots <= 2
        ):
            raise ValueError(f"atom dots must be in 0..2, got {self.dots!r}")
        if self.tuplet is not None and not self.tuplet:
            raise ValueError("atom tuplet must be None or a non-empty label")
        if self.tuplet_group_start and self.tuplet is None:
            raise ValueError("tuplet_group_start requires a tuplet atom")

    def to_dict(self) -> dict[str, Any]:
        return {
            "durationBeats": _frac(self.duration_beats),
            "symbol": self.symbol,
            "dots": self.dots,
            "tuplet": self.tuplet,
            "tupletGroupStart": self.tuplet_group_start,
            "tieToNext": self.tie_to_next,
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreAtom:
        return cls(
            duration_beats=_unfrac(data["durationBeats"]),
            symbol=str(data["symbol"]),
            dots=int(data.get("dots", 0)),
            tuplet=data.get("tuplet"),
            tuplet_group_start=bool(data.get("tupletGroupStart", False)),
            tie_to_next=bool(data.get("tieToNext", False)),
        )


@dataclass(frozen=True)
class ScoreRest:
    """A realized rest span: start position plus its written rest atoms.

    Rests carry no canonical identity (``ids.py``: rest ``note/@id`` values
    are presentation-only). The atoms tile ``[start_beat, start_beat +
    total)`` exactly, never tie, and never cross a barline — a multi-measure
    rest span contains one atom group per measure (a complete empty measure
    is a single ``"whole"`` atom = the measure-rest convention).
    """

    start_beat: Fraction
    atoms: tuple[ScoreAtom, ...]

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(self, "atoms", tuple(self.atoms))
        if self.start_beat < 0:
            raise ValueError(f"rest start_beat must be >= 0, got {self.start_beat}")
        if not self.atoms:
            raise ValueError("a rest span needs at least one atom")
        for atom in self.atoms:
            if not isinstance(atom, ScoreAtom):
                raise TypeError(f"expected ScoreAtom, got {atom!r}")
            if atom.tie_to_next:
                raise ValueError("rest atoms cannot tie to the next atom")

    @property
    def duration_beats(self) -> Fraction:
        """Total exact span covered by the rest atoms."""
        return sum((a.duration_beats for a in self.atoms), Fraction(0))

    @property
    def end_beat(self) -> Fraction:
        """End of the rest span (exclusive)."""
        return self.start_beat + self.duration_beats

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "atoms": [a.to_dict() for a in self.atoms],
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreRest:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            atoms=tuple(ScoreAtom.from_dict(a) for a in data.get("atoms", ())),
        )


@dataclass(frozen=True)
class QuantizedNote:
    """A canonical score note in rational beat positions.

    ``atoms`` is the optional written decomposition committed by the
    quantizer (QNT-006): when present it tiles ``duration_beats`` exactly,
    every atom but the last carries ``tie_to_next``, and no atom crosses a
    barline (barline/beat splits are already materialized as separate tied
    atoms). When empty the notation layer falls back to deriving the written
    decomposition itself (legacy/provisional scores).
    """

    id: ScoreNoteId
    source_event_ids: tuple[RawNoteEventId, ...]
    pitch_midi: int
    start_beat: Fraction
    duration_beats: Fraction
    velocity: int | None = None
    tie_start: bool = False
    tie_stop: bool = False
    atoms: tuple[ScoreAtom, ...] = ()
    # #174: performed pitch-bend curve carried from the backend evidence,
    # normalized to this note's span (PitchBendPoint.time_sec = 0..1).
    # Omitted from serialization when empty so older payloads keep their
    # content-derived revision ids.
    pitch_bends: tuple[PitchBendPoint, ...] = ()

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(self, "duration_beats", _unfrac(self.duration_beats))
        object.__setattr__(self, "atoms", tuple(self.atoms))
        object.__setattr__(self, "pitch_bends", tuple(self.pitch_bends))
        if self.start_beat < 0:
            raise ValueError(f"start_beat must be >= 0, got {self.start_beat}")
        if self.duration_beats <= 0:
            raise ValueError(f"duration_beats must be > 0, got {self.duration_beats}")
        if self.atoms:
            for atom in self.atoms:
                if not isinstance(atom, ScoreAtom):
                    raise TypeError(f"expected ScoreAtom, got {atom!r}")
            total = sum((a.duration_beats for a in self.atoms), Fraction(0))
            if total != self.duration_beats:
                raise ValueError(
                    f"note atoms total {total} != duration_beats {self.duration_beats}"
                )
            if self.atoms[-1].tie_to_next:
                raise ValueError("a note's last atom cannot tie_to_next")
            for atom in self.atoms[:-1]:
                if not atom.tie_to_next:
                    raise ValueError(
                        "interior atoms of a note must tie to the next atom "
                        "(an untied boundary would read as two notes)"
                    )

    @property
    def end_beat(self) -> Fraction:
        """End of the note span (exclusive)."""
        return self.start_beat + self.duration_beats

    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "id": str(self.id),
            "sourceEventIds": [str(e) for e in self.source_event_ids],
            "pitchMidi": self.pitch_midi,
            "startBeat": _frac(self.start_beat),
            "durationBeats": _frac(self.duration_beats),
            "velocity": self.velocity,
            "tieStart": self.tie_start,
            "tieStop": self.tie_stop,
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs (content-derived identity, ids.py).
        if self.atoms:
            data["atoms"] = [a.to_dict() for a in self.atoms]
        if self.pitch_bends:
            data["pitchBends"] = [b.to_dict() for b in self.pitch_bends]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> QuantizedNote:
        return cls(
            id=ScoreNoteId(data["id"]),
            source_event_ids=tuple(RawNoteEventId(e) for e in data.get("sourceEventIds", ())),
            pitch_midi=int(data["pitchMidi"]),
            start_beat=_unfrac(data["startBeat"]),
            duration_beats=_unfrac(data["durationBeats"]),
            velocity=data.get("velocity"),
            tie_start=bool(data.get("tieStart", False)),
            tie_stop=bool(data.get("tieStop", False)),
            atoms=tuple(ScoreAtom.from_dict(a) for a in data.get("atoms", ())),
            pitch_bends=tuple(
                PitchBendPoint.from_dict(b) for b in data.get("pitchBends", ())
            ),
        )


@dataclass(frozen=True)
class TempoSegment:
    start_beat: Fraction
    bpm: float

    def to_dict(self) -> dict[str, Any]:
        return {"startBeat": _frac(self.start_beat), "bpm": self.bpm}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TempoSegment:
        return cls(start_beat=_unfrac(data["startBeat"]), bpm=float(data["bpm"]))


@dataclass(frozen=True)
class TimeSignature:
    beats_per_measure: int
    beat_unit: int

    def to_dict(self) -> dict[str, Any]:
        return {"beatsPerMeasure": self.beats_per_measure, "beatUnit": self.beat_unit}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> TimeSignature:
        return cls(
            beats_per_measure=int(data["beatsPerMeasure"]),
            beat_unit=int(data["beatUnit"]),
        )


@dataclass(frozen=True)
class KeySignature:
    """Fifths (-7..7) plus mode."""

    fifths: int
    mode: str = "major"

    def to_dict(self) -> dict[str, Any]:
        return {"fifths": self.fifths, "mode": self.mode}

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> KeySignature:
        return cls(fifths=int(data["fifths"]), mode=str(data.get("mode", "major")))


@dataclass(frozen=True)
class KeyChange:
    """A key-signature boundary on the canonical beat axis (#133).

    The key_signature is active from start_beat until the next
    change's start_beat (or indefinitely for the last change) —
    the key-map analogue of MeterChange, without a phase concept
    (keys do not affect measure layout).
    """

    start_beat: Fraction
    key_signature: KeySignature

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        if self.start_beat < 0:
            raise ValueError(
                f"key change start_beat must be >= 0, got {self.start_beat}"
            )

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "keySignature": self.key_signature.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> KeyChange:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            key_signature=KeySignature.from_dict(data["keySignature"]),
        )


@dataclass(frozen=True)
class MeterChange:
    """A meter segment boundary on the canonical beat axis (QNT-006).

    The meter ``time_signature`` is active from ``start_beat`` until the
    next change's ``start_beat`` (or indefinitely for the last change).
    ``measure_phase_beats`` is the metrical offset of ``start_beat`` inside
    its measure cycle — the mid-piece analogue of ``pickup_beats``: ``0``
    means the change lands on a downbeat; ``p > 0`` means the segment's
    first measure covers only its last ``measure_length - p`` beats.
    """

    start_beat: Fraction
    time_signature: TimeSignature
    measure_phase_beats: Fraction = Fraction(0)

    def __post_init__(self) -> None:
        object.__setattr__(self, "start_beat", _unfrac(self.start_beat))
        object.__setattr__(
            self, "measure_phase_beats", _unfrac(self.measure_phase_beats)
        )
        if self.start_beat < 0:
            raise ValueError(f"meter change start_beat must be >= 0, got {self.start_beat}")
        if self.measure_phase_beats < 0:
            raise ValueError(
                f"measure_phase_beats must be >= 0, got {self.measure_phase_beats}"
            )
        # The upper bound (phase < measure length) needs the canonical beat
        # unit, which only the owning ScoreRevisionPayload knows — it is
        # validated there.

    def to_dict(self) -> dict[str, Any]:
        return {
            "startBeat": _frac(self.start_beat),
            "timeSignature": self.time_signature.to_dict(),
            "measurePhaseBeats": _frac(self.measure_phase_beats),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> MeterChange:
        return cls(
            start_beat=_unfrac(data["startBeat"]),
            time_signature=TimeSignature.from_dict(data["timeSignature"]),
            measure_phase_beats=_unfrac(data.get("measurePhaseBeats", "0/1")),
        )


@dataclass(frozen=True)
class Part:
    """A single staff part containing canonical notes in score order.

    ``rests`` is the committed rest list (QNT-006): when non-empty the
    notation layer renders exactly these rest atoms and requires notes+rests
    to tile every measure — no gap-filling. When empty (legacy/provisional
    scores) the notation layer fills inter-note gaps itself.
    """

    id: str
    name: str
    notes: tuple[QuantizedNote, ...] = field(default_factory=tuple)
    rests: tuple[ScoreRest, ...] = field(default_factory=tuple)

    def __post_init__(self) -> None:
        object.__setattr__(self, "notes", tuple(self.notes))
        object.__setattr__(self, "rests", tuple(self.rests))
        ordered = sorted(self.rests, key=lambda r: r.start_beat)
        if tuple(ordered) != self.rests:
            raise ValueError("part rests must be in start_beat order")
        for prev, cur in pairwise(self.rests):
            if cur.start_beat < prev.end_beat:
                raise ValueError(
                    f"overlapping rests: {prev.start_beat}+{prev.duration_beats} "
                    f"vs {cur.start_beat}"
                )

    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "id": self.id,
            "name": self.name,
            "notes": [n.to_dict() for n in self.notes],
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs.
        if self.rests:
            data["rests"] = [r.to_dict() for r in self.rests]
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> Part:
        return cls(
            id=str(data["id"]),
            name=str(data["name"]),
            notes=tuple(QuantizedNote.from_dict(n) for n in data.get("notes", ())),
            rests=tuple(ScoreRest.from_dict(r) for r in data.get("rests", ())),
        )


def _frac(value: Fraction) -> str:
    return f"{value.numerator}/{value.denominator}"


def _unfrac(value: Any) -> Fraction:
    if isinstance(value, Fraction):
        return value
    if isinstance(value, str):
        return Fraction(value)
    return Fraction(value)


@dataclass(frozen=True)
class ScoreRevisionPayload:
    """The canonical content a score revision ID is derived from.

    Anything that changes the *musical content* of the score belongs here so
    that revision IDs track content, not serialization accidents.

    ``meter_changes`` is the full ordered meter map when the piece changes
    meter (QNT-006); when present it is authoritative for measure layout,
    its first entry must sit at beat ``0`` with ``time_signature`` matching
    the payload's own ``time_signature`` field, and its first
    ``measure_phase_beats`` must agree with ``pickup_beats``. When empty,
    layout derives from ``time_signature`` + ``pickup_beats`` alone (the
    single-meter legacy path).
    """

    tempo_map: tuple[TempoSegment, ...]
    time_signature: TimeSignature
    key_signature: KeySignature
    pickup_beats: Fraction
    parts: tuple[Part, ...]
    quantization_settings: dict[str, Any]
    meter_changes: tuple[MeterChange, ...] = ()
    """#133: key-signature boundaries — mirrors meter_changes (first
    entry at beat 0 carrying the payload key_signature, strictly
    increasing starts). Empty = single-key legacy path."""
    key_changes: tuple[KeyChange, ...] = ()
    """#134: detected swing feel — the offbeat phase (fraction of a
    notated beat) the piece swings to, e.g. 2/3 for a hard shuffle.
    None = straight. Notation renders a swing direction + playback
    hint; the written rhythm itself is left alone."""
    swing_feel: Fraction | None = None

    def __post_init__(self) -> None:
        object.__setattr__(self, "tempo_map", tuple(self.tempo_map))
        object.__setattr__(self, "parts", tuple(self.parts))
        object.__setattr__(self, "meter_changes", tuple(self.meter_changes))
        object.__setattr__(self, "key_changes", tuple(self.key_changes))
        object.__setattr__(self, "pickup_beats", _unfrac(self.pickup_beats))
        if self.swing_feel is not None:
            object.__setattr__(self, "swing_feel", _unfrac(self.swing_feel))
            if not (Fraction(0) < self.swing_feel < Fraction(1)):
                raise ValueError(
                    f"swing_feel must be a beat fraction in (0, 1), got "
                    f"{self.swing_feel}"
                )
        if self.pickup_beats < 0:
            raise ValueError(f"pickup_beats must be >= 0, got {self.pickup_beats}")
        ts0 = self.time_signature
        if ts0.beats_per_measure <= 0 or ts0.beat_unit <= 0:
            raise ValueError(
                f"invalid time signature: {ts0.beats_per_measure}/{ts0.beat_unit}"
            )
        if self.key_changes:
            if self.key_changes[0].start_beat != 0:
                raise ValueError(
                    "first key change must start at beat 0, got "
                    f"{self.key_changes[0].start_beat}"
                )
            if self.key_changes[0].key_signature != self.key_signature:
                raise ValueError(
                    "first key change must carry the payload key_signature: "
                    f"{self.key_changes[0].key_signature} != {self.key_signature}"
                )
            for prev_key, cur_key in pairwise(self.key_changes):
                if cur_key.start_beat <= prev_key.start_beat:
                    raise ValueError(
                        "key changes must be strictly increasing: "
                        f"{prev_key.start_beat} !< {cur_key.start_beat}"
                    )
        if not self.meter_changes:
            # Legacy single-meter path: pickup must fit inside a measure of
            # the (beat-defining) first time signature.
            if self.pickup_beats >= ts0.beats_per_measure:
                raise ValueError(
                    f"pickup_beats {self.pickup_beats} must be shorter than a "
                    f"{ts0.beats_per_measure}-beat measure"
                )
            return
        first = self.meter_changes[0]
        if first.start_beat != 0:
            raise ValueError(
                f"first meter change must start at beat 0, got {first.start_beat}"
            )
        if first.time_signature != ts0:
            raise ValueError(
                "first meter change must carry the payload time_signature: "
                f"{first.time_signature} != {ts0}"
            )
        beat_ql = Fraction(4, ts0.beat_unit)
        expected_phase = (
            Fraction(ts0.beats_per_measure) - self.pickup_beats
            if self.pickup_beats > 0
            else Fraction(0)
        )
        if first.measure_phase_beats != expected_phase:
            raise ValueError(
                f"first meter change phase {first.measure_phase_beats} "
                f"disagrees with pickup_beats {self.pickup_beats} "
                f"(expected {expected_phase})"
            )
        for prev, cur in pairwise(self.meter_changes):
            if cur.start_beat <= prev.start_beat:
                raise ValueError(
                    "meter changes must be strictly increasing: "
                    f"{prev.start_beat} !< {cur.start_beat}"
                )
        for change in self.meter_changes:
            mlen = measure_length_beats(change.time_signature, beat_ql)
            if change.measure_phase_beats >= mlen:
                raise ValueError(
                    f"meter change at {change.start_beat} has phase "
                    f"{change.measure_phase_beats} >= measure length {mlen}"
                )
    def to_dict(self) -> dict[str, Any]:
        data: dict[str, Any] = {
            "tempoMap": [t.to_dict() for t in self.tempo_map],
            "timeSignature": self.time_signature.to_dict(),
            "keySignature": self.key_signature.to_dict(),
            "pickupBeats": _frac(self.pickup_beats),
            "parts": [p.to_dict() for p in self.parts],
            "quantizationSettings": self.quantization_settings,
        }
        # Omitted when absent so pre-QNT-006 payloads keep their derived
        # revision IDs.
        if self.meter_changes:
            data["meterChanges"] = [m.to_dict() for m in self.meter_changes]
        if self.key_changes:
            data["keyChanges"] = [k.to_dict() for k in self.key_changes]
        if self.swing_feel is not None:
            data["swingFeel"] = _frac(self.swing_feel)
        return data

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreRevisionPayload:
        return cls(
            tempo_map=tuple(TempoSegment.from_dict(t) for t in data.get("tempoMap", ())),
            time_signature=TimeSignature.from_dict(data["timeSignature"]),
            key_signature=KeySignature.from_dict(data["keySignature"]),
            pickup_beats=_unfrac(data.get("pickupBeats", "0/1")),
            parts=tuple(Part.from_dict(p) for p in data.get("parts", ())),
            quantization_settings=dict(data.get("quantizationSettings", {})),
            meter_changes=tuple(
                MeterChange.from_dict(m) for m in data.get("meterChanges", ())
            ),
            key_changes=tuple(
                KeyChange.from_dict(k) for k in data.get("keyChanges", ())
            ),
            swing_feel=(
                _unfrac(data["swingFeel"])
                if data.get("swingFeel") is not None
                else None
            ),
        )

    def revision_id(self) -> ScoreRevisionId:
        return derive_score_revision_id(self.to_dict())


def beat_ql_of(payload: ScoreRevisionPayload) -> Fraction:
    """QuarterLength of one canonical beat — set by the first time signature.

    With a single meter this is simply ``4/beat_unit``. With meter changes
    the *first* meter change defines the beat axis for the whole score, so
    positions stay comparable across segment boundaries.
    """
    return Fraction(4, payload.time_signature.beat_unit)


def measure_length_beats(ts: TimeSignature, beat_ql: Fraction) -> Fraction:
    """One measure of *ts* expressed in canonical beats.

    ``ts.beats_per_measure * (4/beat_unit)`` gives the measure length in
    quarterLength; dividing by ``beat_ql`` converts to canonical beats
    (for the beat-defining signature this is just ``beats_per_measure``).
    """
    if ts.beats_per_measure <= 0 or ts.beat_unit <= 0:
        raise ValueError(
            f"invalid time signature: {ts.beats_per_measure}/{ts.beat_unit}"
        )
    return Fraction(ts.beats_per_measure * 4, ts.beat_unit) / beat_ql


def primary_beat_beats(ts: TimeSignature, beat_ql: Fraction) -> Fraction:
    """Length of one primary (felt) beat of *ts* in canonical beats.

    Compound meters (``numerator % 3 == 0 and numerator > 3`` — e.g. 6/8)
    have ``numerator // 3`` dotted beats; simple meters beat on the
    denominator unit. Mirrors ``MeterSegment.beat_unit_ql`` (design 7.3).
    """
    if ts.beats_per_measure <= 0 or ts.beat_unit <= 0:
        raise ValueError(
            f"invalid time signature: {ts.beats_per_measure}/{ts.beat_unit}"
        )
    beat_count = (
        ts.beats_per_measure // 3
        if ts.beats_per_measure % 3 == 0 and ts.beats_per_measure > 3
        else ts.beats_per_measure
    )
    return measure_length_beats(ts, beat_ql) / beat_count


def note_layers(notes: tuple[QuantizedNote, ...]) -> dict[ScoreNoteId, int]:
    """Assign each note a notation layer (voice) within its part (#155).

    Notes sharing ``(start_beat, duration_beats, atoms)`` — the chord
    condition — are chord members and share one layer.  Any other
    overlap needs its own layer: layers are allocated greedily so the
    lowest free layer wins.  Monophonic parts get all-zero layers, so
    this is a strict generalization of the old one-voice-per-part rule.
    """
    groups: dict[tuple[Fraction, Fraction, tuple[ScoreAtom, ...]], list[QuantizedNote]] = {}
    for n in sorted(notes, key=lambda n: (n.start_beat, n.pitch_midi, n.id)):
        groups.setdefault((n.start_beat, n.duration_beats, n.atoms), []).append(n)
    layer_ends: list[Fraction] = []
    out: dict[ScoreNoteId, int] = {}
    for members in groups.values():
        start = members[0].start_beat
        end = members[0].end_beat
        layer = 0
        while layer < len(layer_ends) and layer_ends[layer] > start:
            layer += 1
        if layer == len(layer_ends):
            layer_ends.append(end)
        else:
            layer_ends[layer] = end
        for n in members:
            out[n.id] = layer
    return out


@dataclass(frozen=True)
class MeasureSpan:
    """One measure's span on the canonical beat axis.

    ``number`` is the MusicXML measure number (``0`` for the implicit
    anacrusis measure); ``time_signature`` is the meter active inside the
    measure; ``meter_change`` marks the first measure of a new meter — the
    notation layer emits ``<time>`` attributes there;
    ``cycle_offset_beats`` is the span's position inside its meter's measure
    cycle (``0`` except for the partial first measure of a phased segment).
    """

    number: int
    start_beat: Fraction
    end_beat: Fraction
    time_signature: TimeSignature
    meter_change: bool = False
    implicit: bool = False
    cycle_offset_beats: Fraction = Fraction(0)

    @property
    def duration_beats(self) -> Fraction:
        return self.end_beat - self.start_beat


def measure_spans(payload: ScoreRevisionPayload) -> tuple[MeasureSpan, ...]:
    """Deterministic measure layout shared by every part and every consumer.

    Layout rules (QNT-006):

    * each meter change tiles measures from its ``start_beat`` until the next
      change (or the content end for the last change), each first measure
      shortened by its ``measure_phase_beats``;
    * a meter change that falls inside a previous measure *clips* it — the
      partial measure keeps its number;
    * a ``measure_phase_beats > 0`` on the *first* change is the anacrusis:
      measure ``0`` with ``implicit`` (the existing convention); phased
      mid-piece changes keep regular numbering;
    * every segment emits at least one measure, so a meter declared beyond
      the content end still appears (as an empty measure);
    * with no ``meter_changes`` this degenerates to the historical layout:
      optional implicit pickup measure plus ``beats_per_measure`` tiling.
    """
    changes = payload.meter_changes
    if not changes:
        ts0 = payload.time_signature
        mlen0 = Fraction(ts0.beats_per_measure)
        phase0 = (
            mlen0 - payload.pickup_beats if payload.pickup_beats > 0 else Fraction(0)
        )
        changes = (MeterChange(Fraction(0), ts0, phase0),)
    beat_ql = beat_ql_of(payload)

    end = payload.pickup_beats
    for part in payload.parts:
        for n in part.notes:
            end = max(end, n.end_beat)
        for r in part.rests:
            end = max(end, r.end_beat)

    spans: list[MeasureSpan] = []
    number = 1
    for i, change in enumerate(changes):
        seg_end = changes[i + 1].start_beat if i + 1 < len(changes) else None
        mlen = measure_length_beats(change.time_signature, beat_ql)
        pos = change.start_beat
        first = True
        while first or (pos < seg_end if seg_end is not None else pos < end):
            dur = mlen - change.measure_phase_beats if first else mlen
            m_end = pos + dur
            if seg_end is not None and m_end > seg_end:
                m_end = seg_end
            if m_end <= pos:
                break  # safety: zero-length measure
            implicit = first and i == 0 and change.measure_phase_beats > 0
            span_number = 0 if implicit else number
            if not implicit:
                number += 1
            spans.append(
                MeasureSpan(
                    number=span_number,
                    start_beat=pos,
                    end_beat=m_end,
                    time_signature=change.time_signature,
                    meter_change=first and i > 0,
                    implicit=implicit,
                    cycle_offset_beats=(
                        change.measure_phase_beats if first else Fraction(0)
                    ),
                )
            )
            pos = m_end
            first = False
    return tuple(spans)


@dataclass(frozen=True)
class ScoreDocument:
    """Canonical score container. ``payload`` carries all musical content."""

    project_id: ProjectId
    payload: ScoreRevisionPayload
    title: str = ""
    source_audio_path: str | None = None
    source_audio_hash: str | None = None
    transcription_backend: str | None = None
    transcription_backend_version: str | None = None
    transcription_settings: dict[str, Any] = field(default_factory=dict)
    pitch_space: PitchSpace = PitchSpace.CONCERT

    @property
    def revision(self) -> ScoreRevisionId:
        return self.payload.revision_id()

    def to_dict(self) -> dict[str, Any]:
        if self.pitch_space is not PitchSpace.CONCERT:
            raise ValueError("canonical ScoreDocument must be concert pitch")
        return {
            "projectId": str(self.project_id),
            "revision": str(self.revision),
            "title": self.title,
            "sourceAudioPath": self.source_audio_path,
            "sourceAudioHash": self.source_audio_hash,
            "transcriptionBackend": self.transcription_backend,
            "transcriptionBackendVersion": self.transcription_backend_version,
            "transcriptionSettings": self.transcription_settings,
            "pitchSpace": self.pitch_space.value,
            "content": self.payload.to_dict(),
        }

    @classmethod
    def from_dict(cls, data: dict[str, Any]) -> ScoreDocument:
        space = PitchSpace(data.get("pitchSpace", "concert"))
        doc = cls(
            project_id=ProjectId(data["projectId"]),
            payload=ScoreRevisionPayload.from_dict(data["content"]),
            title=str(data.get("title", "")),
            source_audio_path=data.get("sourceAudioPath"),
            source_audio_hash=data.get("sourceAudioHash"),
            transcription_backend=data.get("transcriptionBackend"),
            transcription_backend_version=data.get("transcriptionBackendVersion"),
            transcription_settings=dict(data.get("transcriptionSettings", {})),
            pitch_space=space,
        )
        declared = data.get("revision")
        if declared is not None and declared != str(doc.revision):
            raise ValueError(
                f"score revision mismatch: declared {declared} != derived {doc.revision}"
            )
        return doc


def new_project_id() -> ProjectId:
    """Random project ID for genuinely new projects (creation-time only)."""
    from hornscribe.domain.ids import derive_project_id

    return derive_project_id({"uuid": uuid.uuid4().hex})

"""Score-level rhythm edits on the canonical payload (#115, spec 13).

The simple note edits (pitch shift, delete/restore, enharmonic respell)
are MusicXML-level rewrites the desktop applies client-side. The three
remaining §13 edits change *timing*, so they must re-realize notation:

* ``setDuration`` — a new written duration for one canonical note;
* ``shiftOnset`` — move a note by whole minimum-grid steps;
* ``toggleTie`` — tie/untie a note to the contiguous next same-pitch
  note (a flag pair on the canonical notes; atoms are untouched).
* ``scaleTempo`` — the tempo-octave correction (#198): scales the
  tempo map AND every beat-axis position/duration by the same factor,
  so notation values change while wall-clock playback stays put (the
  inverse of ``setTempo``, which relabels BPM only).

Timing edits rebuild the smallest measure-aligned window containing
the note's old and new spans: notes inside are re-decomposed through
the same :class:`SpanRealizer` the quantizer used, gaps become rests,
and the monophonic contract is re-applied (a note may never cross the
next onset — an edit that would is rejected, not silently clipped).
"""

